{
  "understanding": {
    "purpose": "按目的地区域和省份查询物流首重、续重费用与预计时效，并说明偏远地区的特殊运费。",
    "reading": "读者先定位地区和省份，再横向读取费用与时效；也可能纵向比较不同目的地的价格和时效。合并的地区单元格将相邻省份组成一组，偏远地区说明则横跨后四列。",
    "groups": [
      "目的地区域与省份共同确定目的地，应保持清晰的层级和相邻关系。",
      "首重与续重都是运费指标，应便于横向读取和纵向比较。",
      "时效与费用共同构成物流服务信息，但较长的时效文字需要更多弹性空间。"
    ],
    "keep_intact": [
      "地区和省份名称尽量保持完整。",
      "首重、续重的数值及其单位应清晰可辨，避免拆开数字或单位。",
      "时效中的数字、时间单位及不可分割的标识应保持完整。"
    ],
    "may_wrap": [
      "较长的时效说明可在自然语义边界换行。",
      "偏远地区的跨列说明可自然换行；它拥有后四列的合并宽度。",
      "首重和续重表头可在适当位置换行，但保持表头单行更利于比较。",
      "华东和华南的合并地区单元格各跨两行，其已有高度可以容纳必要的换行。"
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [88, 48, 88, 107, 148],
      "idea": "保持各列表头和目的地名称单行，将剩余宽度交给时效说明，兼顾费用比较与阅读。"
    },
    {
      "name": "B",
      "widths": [75, 48, 75, 81, 200],
      "idea": "收紧地区和费用列，并允许较长表头换行，为时效说明提供更宽的阅读空间。"
    },
    {
      "name": "C",
      "widths": [88, 55, 100, 116, 120],
      "idea": "突出目的地和两项运费的纵向比较，以较窄的时效列换取更从容的费用列节奏。"
    }
  ]
